/*\n  # Automatic Temperature Cooling System\n\n  1. New Functions\n    - `cool_down_inactive_contacts()` - Automatically cools down prospects and leads after 3 months of inactivity\n    \n  2. Activity Tracking\n    - Checks last proposal creation\n    - Checks last connection logged\n    - Checks last contact update\n    - If no activity in 3 months (90 days), temperature reverts to 'cold'\n    \n  3. Scope\n    - Only affects prospects and leads with temperature set to warm, hot, or on_fire\n    - Does not affect customers\n    - Does not cool down contacts that are already cold\n    \n  4. Notes\n    - Can be called via scheduled edge function\n    - Returns count of contacts that were cooled down\n*/\n\n-- Function to automatically cool down inactive prospects and leads\nCREATE OR REPLACE FUNCTION cool_down_inactive_contacts()\nRETURNS TABLE (\n  contact_id uuid,\n  contact_name text,\n  previous_temperature text,\n  days_inactive integer\n)\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  three_months_ago timestamptz := now() - interval '90 days'

\n  cooled_count integer := 0

\nBEGIN\n  -- Find and cool down inactive prospects and leads\n  RETURN QUERY\n  WITH inactive_contacts AS (\n    SELECT \n      c.id,\n      c.full_name,\n      c.temperature,\n      COALESCE(\n        GREATEST(\n          -- Last proposal created for this contact\n          (SELECT MAX(created_at) FROM proposals WHERE contact_id = c.id),\n          -- Last connection logged\n          (SELECT MAX(connection_date) FROM connections WHERE contact_id = c.id),\n          -- Last task created for this contact\n          (SELECT MAX(created_at) FROM tasks WHERE contact_id = c.id),\n          -- Last time contact was updated\n          c.updated_at,\n          c.created_at\n        ),\n        c.created_at\n      ) as last_activity_date,\n      EXTRACT(days FROM now() - COALESCE(\n        GREATEST(\n          (SELECT MAX(created_at) FROM proposals WHERE contact_id = c.id),\n          (SELECT MAX(connection_date) FROM connections WHERE contact_id = c.id),\n          (SELECT MAX(created_at) FROM tasks WHERE contact_id = c.id),\n          c.updated_at,\n          c.created_at\n        ),\n        c.created_at\n      ))::integer as days_since_activity\n    FROM contacts c\n    WHERE \n      -- Only prospects and leads\n      (c.is_prospect = true OR c.contact_type = 'lead')\n      -- Not already cold\n      AND c.temperature != 'cold'\n      -- Has a temperature set\n      AND c.temperature IS NOT NULL\n      -- Last activity was more than 90 days ago\n      AND COALESCE(\n        GREATEST(\n          (SELECT MAX(created_at) FROM proposals WHERE contact_id = c.id),\n          (SELECT MAX(connection_date) FROM connections WHERE contact_id = c.id),\n          (SELECT MAX(created_at) FROM tasks WHERE contact_id = c.id),\n          c.updated_at,\n          c.created_at\n        ),\n        c.created_at\n      ) < three_months_ago\n  )\n  UPDATE contacts c\n  SET \n    temperature = 'cold',\n    updated_at = now()\n  FROM inactive_contacts ic\n  WHERE c.id = ic.id\n  RETURNING \n    c.id as contact_id,\n    ic.full_name as contact_name,\n    ic.temperature as previous_temperature,\n    ic.days_since_activity as days_inactive

\nEND

\n$$

\n\n-- Grant execute permission to authenticated users\nGRANT EXECUTE ON FUNCTION cool_down_inactive_contacts() TO authenticated

\n\n-- Add comment\nCOMMENT ON FUNCTION cool_down_inactive_contacts() IS 'Automatically cools down prospects and leads that have had no activity (proposals, connections, tasks, updates) for 90+ days. Returns list of contacts that were cooled down.'


